// The SUMMARY tab: the central ledger drawn in the same Raster style as the rest of the console.
// Pure (state in, Canvas out) so it can be tested and previewed without Claude Code.

import { Canvas, C, DEFAULT, lerp3 } from './canvas.ts'
import { group, filterRows, colsFor, barValue } from './summary.ts'
import type { Row, Agg, Dim, ColDef } from './summary.ts'
import { fmtUsd, fmtTokens, fmtDur, cacheHit, clamp } from './lib.ts'

export type SView = 'overview' | 'card' | 'day' | 'week' | 'month' | 'model' | 'skill' | 'tool' | 'agent' | 'project' | 'session' | 'detail'
export const SVIEWS: SView[] = ['overview', 'card', 'day', 'model', 'skill', 'agent', 'tool', 'project']
export const RANGE_PRESETS: (number | null)[] = [1, 7, 30, null]

export interface SumState {
  rows: Row[]
  loaded: boolean
  loading: boolean
  loadedAt: number
  note: string
  view: SView
  days: number | null
  sel: number // selected row in the main table
  detailCard: string | null
  now: number
  onLayout?: (info: { visibleRows: number }) => void // told how many rows the selectable table shows, so a page key can jump that far
}

export const rangeLabel = (days: number | null): string => (days == null ? 'all time' : days === 1 ? 'today' : `last ${days} days`)
export const rangeShort = (days: number | null): string => (days == null ? 'ALL' : days === 1 ? 'TODAY' : `${days}D`)

const VIEW_LABEL: Record<SView, string> = {
  overview: 'OVERVIEW', card: 'BY CARD', day: 'BY DAY', week: 'BY WEEK', month: 'BY MONTH', model: 'BY MODEL', skill: 'BY SKILL',
  tool: 'BY TOOL', agent: 'BY AGENT', project: 'BY PROJECT', session: 'BY SESSION', detail: 'CARD',
}

// The rows the main (selectable) table shows for this state.
export function mainAggs(st: SumState): Agg[] {
  const rows = filterRows(st.rows, { days: st.days, card: st.view === 'detail' ? st.detailCard : null }, new Date(st.now))
  const dim: Dim = st.view === 'overview' || st.view === 'card' ? 'card' : st.view === 'detail' ? 'session' : (st.view as Dim)
  return group(rows, dim)
}

// The dimension a view counts: its tables use that dimension's own columns.
export const viewDim = (v: SView): Dim => (v === 'overview' || v === 'card' ? 'card' : v === 'detail' ? 'session' : (v as Dim))

// ---------- drawing helpers ----------
const clip = (s: string, w: number) => (s.length > w ? s.slice(0, Math.max(0, w - 1)) + '…' : s.padEnd(w))
const right = (s: string, w: number) => s.padStart(w)

function highlightRow(cv: Canvas, x0: number, x1: number, y: number) {
  for (let x = x0; x <= x1; x++) {
    const i = y * cv.cols + x
    cv.bg[i] = C.cyan
    const ch = cv.ch[i]
    if (ch !== 0x2588 && ch !== 0x2591) cv.fg[i] = C.ink // keep the bar fill visible
  }
}

// A framed table. `sel` highlights a row and the window follows it.
function drawTable(cv: Canvas, x: number, y: number, w: number, h: number, title: string, aggs: Agg[], keyLabel: string, dim: Dim, sel: number | null, skip: string[] = [], onVisible?: (n: number) => void) {
  if (w < 16 || h < 4) return
  const visible = h - 3 // frame (2) + header (1)
  if (onVisible) onVisible(visible)
  const total = aggs.length
  let start = 0
  if (sel != null && total > visible) start = clamp(sel - Math.floor(visible / 2), 0, total - visible)
  const end = Math.min(total, start + visible)
  cv.frame(x, y, w, h, {
    color: C.cyan, label: title, labelColor: C.hot,
    tab: total > visible ? `${start + 1}-${end} of ${total}` : undefined, tabColor: C.dim,
  })
  const ix = x + 2
  const innerW = w - 4
  // this dimension's own columns, in priority order, while the key column still has 12+ characters; then the bar
  const cols: ColDef[] = []
  let used = 0
  for (const c of colsFor(dim)) {
    if (!c.pane || skip.includes(c.id)) continue
    if (innerW - (used + c.w + 1) >= 12) { cols.push(c); used += c.w + 1 }
  }
  const BAR_W = 6
  const hasBar = innerW - (used + BAR_W + 1) >= 12
  if (hasBar) used += BAR_W + 1
  const kw = innerW - used
  let cx = ix + kw + 1
  cv.text(ix, y + 1, clip(keyLabel, kw), C.dim)
  for (const c of cols) { cv.text(cx, y + 1, right(c.head, c.w), C.dim); cx += c.w + 1 }

  if (total === 0) { cv.text(ix, y + 2, 'nothing recorded for this range', C.dim, DEFAULT, ix + innerW - 1); return }
  const maxBar = Math.max(1e-9, ...aggs.map((a) => barValue(a, dim)))
  for (let i = start; i < end; i++) {
    const a = aggs[i]
    const yy = y + 2 + (i - start)
    const noCard = a.key === '(no card)'
    cv.text(ix, yy, clip(a.key, kw), noCard ? C.dim : C.hot)
    let px = ix + kw + 1
    for (const c of cols) {
      const color = c.id === 'cost' ? C.hot : c.id === 'fail' && a.fail > 0 ? C.alert : c.id === 'last' ? C.dim : C.text
      cv.text(px, yy, right(c.get(a), c.w), color)
      px += c.w + 1
    }
    if (hasBar) cv.bar(px, yy, BAR_W, barValue(a, dim) / maxBar, C.cyan, C.deep, C.magenta)
    if (sel === i) highlightRow(cv, ix - 1, ix + innerW, yy)
  }
}

// ---------- the pane ----------
export function renderSummaryPane(st: SumState, cols: number, rows: number): Canvas {
  const H = Math.max(10, rows)
  const cv = new Canvas(cols, H)
  const body = H - 1
  const detail = st.view === 'detail'

  // headline panel
  const filtered = filterRows(st.rows, { days: st.days, card: detail ? st.detailCard : null }, new Date(st.now))
  const sum = (f: (r: Row) => number) => filtered.reduce((s, r) => s + f(r), 0)
  const cost = sum((r) => r.costUsd)
  const out = sum((r) => r.out)
  const inn = sum((r) => r.in)
  const cr = sum((r) => r.cacheRead)
  const cw = sum((r) => r.cacheWrite)
  const sessions = new Set(filtered.map((r) => r.session)).size
  const headTitle = detail ? `CARD ${st.detailCard}` : 'GRID SUMMARY'
  cv.frame(0, 0, cols, 4, { color: C.hot, label: headTitle, labelColor: C.white, tab: `${rangeShort(st.days)} · ${VIEW_LABEL[st.view]}`, tabColor: C.cyan, tabInset: 6 })
  const stat = (x: number, y: number, label: string, value: string, color: number = C.hot) => {
    const e = cv.text(x, y, label + ' ', C.dim)
    return cv.text(e, y, value, color) + 2
  }
  if (!st.loaded) {
    cv.text(2, 1, st.loading ? 'reading every session in ~/.claude/claudegrid …' : 'press u to load', C.dim)
  } else if (filtered.length === 0) {
    cv.text(2, 1, `no turns recorded for ${detail ? st.detailCard + ' in ' : ''}${rangeLabel(st.days)}`, C.dim)
    cv.text(2, 2, st.note.includes('loose') ? st.note : 'press r for a wider range, or b to go back', st.note.includes('loose') ? C.alert : C.dim, DEFAULT, cols - 3)
  } else {
    let x = 2
    x = stat(x, 1, 'SESSIONS', String(sessions))
    x = stat(x, 1, 'TURNS', String(filtered.length))
    x = stat(x, 1, 'COST', fmtUsd(cost))
    x = stat(x, 1, 'CLAUDE TIME', fmtDur(sum((r) => r.durationMs)))
    x = 2
    x = stat(x, 2, 'OUT', fmtTokens(out))
    x = stat(x, 2, 'IN', fmtTokens(inn))
    x = stat(x, 2, 'CACHE R', fmtTokens(cr), C.text)
    x = stat(x, 2, 'W', fmtTokens(cw), C.text)
    x = stat(x, 2, 'HIT', Math.round(cacheHit(inn, cr, cw) * 100) + '%')
    x = stat(x, 2, 'TOOLS', String(sum((r) => r.toolCalls)))
  }

  // main area
  const top = 4
  const areaH = body - top
  const aggs = st.loaded ? mainAggs(st) : []
  const sel = aggs.length ? clamp(st.sel, 0, aggs.length - 1) : null
  const dim = viewDim(st.view)
  const keyLabel = detail ? 'SESSION' : st.view === 'overview' || st.view === 'card' ? 'CARD' : VIEW_LABEL[st.view].replace('BY ', '')
  const mainTitle = detail ? 'SESSIONS' : st.view === 'overview' ? 'BY CARD  (↑↓ select, Enter opens)' : st.view === 'skill' || st.view === 'agent' ? `${VIEW_LABEL[st.view]}  (* whole turns that used it)` : VIEW_LABEL[st.view]
  const multi = (st.view === 'overview' || detail) && st.loaded && filtered.length > 0 && areaH >= 14
  const skip: string[] = detail ? ['sess'] : [] // every row in a list of sessions is one session
  const vis = (n: number) => st.onLayout?.({ visibleRows: n })

  // Panels stacked in a column; each gets the rows it wants, and later ones are dropped if there is no room.
  const stack = (x: number, y0: number, w: number, h: number, defs: [string, Dim, string, number][]) => {
    const groups = defs.map(([title, dim, label, n]) => ({ title, dim, label, list: group(filtered, dim).slice(0, n) })).filter((g) => g.list.length > 0)
    let remaining = h
    let y = y0
    groups.forEach((g, i) => {
      const left = groups.length - i - 1
      const ph = Math.min(g.list.length + 3, remaining - left * 4)
      if (ph >= 4) { drawTable(cv, x, y, w, ph, g.title, g.list, g.label, g.dim, null); y += ph; remaining -= ph }
    })
  }

  if (multi) {
    const mainRows = detail ? aggs.map((a) => ({ ...a, key: a.key.slice(0, 8) })) : aggs
    const side: [string, Dim, string, number][] = [
      ['BY MODEL', 'model', 'MODEL', 4], [detail ? 'SKILLS' : 'TOP SKILLS', 'skill', 'SKILL', 4],
      [detail ? 'AGENTS' : 'TOP AGENTS', 'agent', 'AGENT', 3], [detail ? 'TOOLS' : 'TOP TOOLS', 'tool', 'TOOL', 5],
    ]
    if (cols >= 76) {
      // two columns: the main table with the days under it, and models, skills, agents and tools beside
      const leftW = Math.floor(cols * 0.55)
      const mainH = clamp(aggs.length + 3, 6, Math.floor(areaH * 0.55))
      drawTable(cv, 0, top, leftW, mainH, mainTitle, mainRows, keyLabel, dim, sel, skip, vis)
      const days = group(filtered, 'day').slice(0, 14)
      const dayH = Math.min(days.length + 3, areaH - mainH)
      if (dayH >= 4) drawTable(cv, 0, top + mainH, leftW, dayH, 'BY DAY', days, 'DAY', 'day', null)
      stack(leftW, top, cols - leftW, areaH, side)
    } else {
      // a narrow pane: one column, everything stacked under the main table
      const mainH = clamp(aggs.length + 3, 6, Math.floor(areaH * 0.35))
      drawTable(cv, 0, top, cols, mainH, mainTitle, mainRows, keyLabel, dim, sel, skip, vis)
      stack(0, top + mainH, cols, areaH - mainH, [['BY DAY', 'day', 'DAY', 7], ...side])
    }
  } else {
    drawTable(cv, 0, top, cols, areaH, mainTitle, aggs, keyLabel, dim, sel, skip, vis)
  }

  // status strip, like the other tabs
  const bar = ` 3 [summary]  ${rangeLabel(st.days)}  ${VIEW_LABEL[st.view].toLowerCase()}  ${st.loaded ? st.rows.length + ' turns on file' : 'loading'}`
  const note = st.loaded ? ` ${st.note} ` : ''
  for (let x = 0; x < cols; x++) cv.set(x, H - 1, 32, C.ink, lerp3(C.cyan, C.blue, C.magenta, x / Math.max(1, cols - 1)))
  cv.text(0, H - 1, bar, C.ink)
  if (note.length < cols - bar.length - 2) cv.text(cols - note.length, H - 1, note, C.ink)
  return cv
}

files.hooks/sysmon.ts:
// Parsers for the SYSTEM tab. Text in, numbers out, no Claude Code APIs: the mod collects the raw text (from `vm_stat`, `top`,
// `sysctl`, `pmset`, `ps` on macOS; /proc and /sys on Linux) and these functions turn it into a Sample.

export type Platform = 'darwin' | 'linux' | 'other'

export interface Mem {
  total: number // bytes
  used: number
  cached: number
  free: number
  app?: number // macOS: app memory, wired and compressed are what Activity Monitor adds up to "Memory Used"
  wired?: number
  compressed?: number
}
export interface CpuUse { total: number; user: number; sys: number } // percent, 0 to 100
export interface Proc { pid: number; cpu: number; rssKb: number; name: string }
export interface Thermal { state: 'nominal' | 'throttled' | 'unknown'; limit?: number } // macOS thermal pressure, not a temperature
export type Pressure = 'normal' | 'warn' | 'critical'

export interface Sample {
  at: number
  platform: Platform
  cores: number | null
  cpu: CpuUse | null
  perCore: number[] | null
  load: [number, number, number] | null
  mem: Mem | null
  swap: { total: number; used: number } | null
  pressure: Pressure | null
  thermal: Thermal | null
  procs: Proc[]
  notes: string[] // what could not be read, and why
}

const UNIT: Record<string, number> = { K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 }

// ---------- macOS ----------

// vm_stat, with the machine's total memory. Follows Activity Monitor: Memory Used = App Memory + Wired + Compressed,
// where App Memory is anonymous pages less purgeable ones, and "cached files" are file-backed plus purgeable pages.
export function parseVmStat(text: string, totalBytes: number): Mem | null {
  const pageSize = Number(/page size of (\d+) bytes/.exec(text)?.[1] ?? 4096)
  const get = (label: string): number | null => {
    const m = new RegExp(`^"?${label}"?:\\s+(\\d+)`, 'mi').exec(text)
    return m ? Number(m[1]) : null
  }
  const wired = get('Pages wired down')
  if (wired == null) return null
  const free = get('Pages free') ?? 0
  const spec = get('Pages speculative') ?? 0
  const active = get('Pages active') ?? 0
  const inactive = get('Pages inactive') ?? 0
  const purgeable = get('Pages purgeable') ?? 0
  const anon = get('Anonymous pages')
  const file = get('File-backed pages')
  const comp = get('Pages occupied by compressor') ?? 0
  const P = (n: number) => n * pageSize
  const app = anon != null ? Math.max(0, P(anon - purgeable)) : P(active)
  const total = totalBytes > 0 ? totalBytes : P(free + spec + active + inactive + wired + comp)
  const used = Math.min(total, app + P(wired) + P(comp))
  const cached = Math.min(total - used, file != null ? P(file + purgeable) : P(inactive + purgeable))
  return { total, used, cached, free: Math.max(0, total - used - cached), app, wired: P(wired), compressed: P(comp) }
}

// The last "CPU usage:" line of `top -l 2` (the first sample is an average since boot, the second is live).
export function parseTopCpu(text: string): CpuUse | null {
  const all = [...text.matchAll(/CPU usage:\s*([\d.]+)%\s*user,\s*([\d.]+)%\s*sys,\s*([\d.]+)%\s*idle/g)]
  const m = all[all.length - 1]
  if (!m) return null
  const user = Number(m[1])
  const sys = Number(m[2])
  const idle = Number(m[3])
  return { total: clamp(100 - idle, 0, 100), user, sys }
}

// "total = 3072.00M  used = 1450.25M  free = 1621.75M  (encrypted)"
export function parseSwapUsage(text: string): { total: number; used: number } | null {
  const m = /total\s*=\s*([\d.]+)([KMGT])\s+used\s*=\s*([\d.]+)([KMGT])/.exec(text)
  return m ? { total: Number(m[1]) * UNIT[m[2]], used: Number(m[3]) * UNIT[m[4]] } : null
}

// kern.memorystatus_vm_pressure_level: 1 normal, 2 warning, 4 critical
export function parsePressure(text: string): Pressure | null {
  const n = Number(text.trim())
  return n === 1 ? 'normal' : n === 2 ? 'warn' : n === 4 ? 'critical' : null
}

// `pmset -g therm` lists "CPU_Speed_Limit = 70" only when the system has been slowed to stay cool.
export function parsePmsetTherm(text: string): Thermal {
  if (!text.trim()) return { state: 'unknown' }
  const m = /CPU_Speed_Limit\s*=\s*(\d+)/.exec(text)
  if (m && Number(m[1]) < 100) return { state: 'throttled', limit: Number(m[1]) }
  return { state: 'nominal' }
}

// ---------- Linux ----------

export function parseMeminfo(text: string): { mem: Mem; swap: { total: number; used: number } } | null {
  const kb = (key: string): number | null => {
    const m = new RegExp(`^${key}:\\s+(\\d+)`, 'mi').exec(text)
    return m ? Number(m[1]) * 1024 : null
  }
  const total = kb('MemTotal')
  if (total == null) return null
  const free = kb('MemFree') ?? 0
  const buffers = kb('Buffers') ?? 0
  const cachedFiles = kb('Cached') ?? 0
  const available = kb('MemAvailable') ?? free + buffers + cachedFiles
  const used = Math.max(0, total - available)
  const swapTotal = kb('SwapTotal') ?? 0
  const swapFree = kb('SwapFree') ?? 0
  return {
    mem: { total, used: Math.min(used, total), cached: Math.min(buffers + cachedFiles, Math.max(0, total - used)), free },
    swap: { total: swapTotal, used: Math.max(0, swapTotal - swapFree) },
  }
}

export interface CpuTimes { name: string; busyUser: number; busySys: number; idle: number; total: number }

// /proc/stat: one "cpu" line for the whole machine and one per core.
export function parseProcStat(text: string): CpuTimes[] {
  const out: CpuTimes[] = []
  for (const line of text.split('\n')) {
    const m = /^(cpu\d*)\s+(.+)$/.exec(line)
    if (!m) continue
    const [user, nice, sys, idle, iowait, irq, softirq, steal] = m[2].trim().split(/\s+/).map(Number)
    if (![user, nice, sys, idle].every(Number.isFinite)) continue
    const idleAll = idle + (iowait || 0)
    const sysAll = sys + (irq || 0) + (softirq || 0)
    out.push({ name: m[1], busyUser: user + nice, busySys: sysAll, idle: idleAll, total: user + nice + sysAll + idleAll + (steal || 0) })
  }
  return out
}

// Utilisation between two reads of the same counter.
export function cpuBetween(prev: CpuTimes, cur: CpuTimes): CpuUse | null {
  const dt = cur.total - prev.total
  if (dt <= 0) return null
  const idle = cur.idle - prev.idle
  return {
    total: clamp(100 * (1 - idle / dt), 0, 100),
    user: clamp((100 * (cur.busyUser - prev.busyUser)) / dt, 0, 100),
    sys: clamp((100 * (cur.busySys - prev.busySys)) / dt, 0, 100),
  }
}

// "0.12 0.20 0.18 1/234 5678" (Linux) or "{ 1.78 1.92 2.01 }" (macOS)
export function parseLoad(text: string): [number, number, number] | null {
  const n = [...text.matchAll(/\d+\.\d+/g)].map((m) => Number(m[0]))
  return n.length >= 3 ? [n[0], n[1], n[2]] : null
}

// ---------- both ----------

// `ps` with pid, %cpu, rss (KiB) and command, one process a line.
export function parsePs(text: string): Proc[] {
  const out: Proc[] = []
  for (const line of text.split('\n')) {
    const m = /^\s*(\d+)\s+([\d.]+)\s+(\d+)\s+(.*\S)\s*$/.exec(line)
    if (!m) continue
    const name = m[4].split('/').filter(Boolean).pop() ?? m[4]
    out.push({ pid: Number(m[1]), cpu: Number(m[2]), rssKb: Number(m[3]), name })
  }
  return out
}

export const topByCpu = (p: Proc[], n: number): Proc[] => [...p].sort((a, b) => b.cpu - a.cpu).slice(0, n)
export const topByMem = (p: Proc[], n: number): Proc[] => [...p].sort((a, b) => b.rssKb - a.rssKb).slice(0, n)

export function fmtBytes(n: number): string {
  if (n < 1024 ** 2) return `${Math.round(n / 1024)}K`
  if (n < 1024 ** 3) return `${Math.round(n / 1024 ** 2)}M`
  const g = n / 1024 ** 3
  return `${g < 10 ? g.toFixed(1) : Math.round(g)}G`
}

const SPARK = '▁▂▃▄▅▆▇█'
// A line chart in one row of block glyphs, newest on the right.
export function spark(values: number[], width: number, max = 100): string {
  const v = values.slice(-width)
  const s = v.map((x) => SPARK[clamp(Math.round((x / max) * 7), 0, 7)]).join('')
  return s.padStart(width, ' ')
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n))
}

files.hooks/sysview.ts:
// The SYSTEM tab: CPU, memory and the busiest processes, drawn like the other tabs.
// Pure (state in, Canvas out) so it can be tested and previewed without Claude Code.

import { Canvas, C, DEFAULT, lerp3 } from './canvas.ts'
import type { Sample } from './sysmon.ts'
import { fmtBytes, spark, topByCpu, topByMem } from './sysmon.ts'
import { clamp } from './lib.ts'

export interface SysState {
  sample: Sample | null
  cpuHist: number[]
  memHist: number[]
  loading: boolean
  error: string
  now: number
  everyMs: number
}

// Primary colour while there is room, then yellow, then the alert colour.
const heat = (frac: number): number => (frac >= 0.85 ? C.alert : frac >= 0.65 ? C.yellow : C.cyan)
const pct = (n: number) => `${Math.round(n)}%`
const clip = (s: string, w: number) => (s.length > w ? s.slice(0, Math.max(0, w - 1)) + '…' : s)

// Break text into lines of at most `w` characters, on spaces.
function wrap(text: string, w: number): string[] {
  const out: string[] = []
  let line = ''
  for (const word of text.split(/\s+/).filter(Boolean)) {
    if (line && (line + ' ' + word).length > w) { out.push(line); line = word }
    else line = line ? line + ' ' + word : word
  }
  if (line) out.push(line)
  return out
}

// ▕█████░░░░▏ with a fill colour that follows the load.
function meter(cv: Canvas, x: number, y: number, w: number, frac: number): void {
  cv.bar(x, y, w, frac, heat(frac), C.deep, frac < 0.65 ? C.magenta : undefined)
}

// A stacked bar: each part gets its share of the width; what is left over is the empty track.
function stacked(cv: Canvas, x: number, y: number, w: number, parts: { frac: number; color: number }[]): void {
  const inner = Math.max(1, w - 2)
  cv.set(x, y, '▕'.codePointAt(0)!, C.dim)
  let at = 0
  for (const p of parts) {
    const n = Math.round(clamp(p.frac, 0, 1) * inner)
    for (let i = 0; i < n && at < inner; i++, at++) cv.set(x + 1 + at, y, '█'.codePointAt(0)!, p.color)
  }
  for (; at < inner; at++) cv.set(x + 1 + at, y, '░'.codePointAt(0)!, C.deep)
  cv.set(x + 1 + inner, y, '▏'.codePointAt(0)!, C.dim)
}

// A sparkline coloured by value.
function sparkline(cv: Canvas, x: number, y: number, w: number, values: number[], max: number): void {
  const s = spark(values, w, max)
  const tail = values.slice(-w)
  for (let i = 0; i < w; i++) {
    const v = tail[i - (w - tail.length)]
    if (v == null) continue
    cv.set(x + i, y, s.codePointAt(i)!, heat(v / max))
  }
}

// A history chart `h` rows tall: each column is one sample, filled from the bottom with block glyphs (eight levels a row).
// With one row it is a sparkline.
function areaChart(cv: Canvas, x: number, y: number, w: number, h: number, values: number[], max: number): void {
  if (h <= 1) { sparkline(cv, x, y, w, values, max); return }
  const LEVELS = ' ▁▂▃▄▅▆▇█'
  const tail = values.slice(-w)
  for (let i = 0; i < tail.length; i++) {
    const col = x + w - tail.length + i
    const eighths = clamp(Math.round((tail[i] / max) * h * 8), 0, h * 8)
    const color = heat(tail[i] / max)
    for (let r = 0; r < h; r++) {
      const fromBottom = h - 1 - r
      const level = clamp(eighths - fromBottom * 8, 0, 8)
      if (level > 0) cv.set(col, y + r, LEVELS.codePointAt(level)!, color)
    }
  }
}

function label(cv: Canvas, x: number, y: number, text: string, color: number = C.dim): number {
  return cv.text(x, y, text, color)
}

// ---------- panels ----------

function cpuPanel(cv: Canvas, s: SysState, x: number, y: number, w: number, h: number): void {
  if (w < 24 || h < 4) return
  const smp = s.sample
  cv.frame(x, y, w, h, { color: C.cyan, label: 'CPU', labelColor: C.hot })
  const ix = x + 2
  const iw = w - 4
  if (!smp?.cpu) { label(cv, ix, y + 1, smp ? 'CPU use is not available here' : 'reading …'); return }
  const c = smp.cpu
  let e = label(cv, ix, y + 1, 'USED ')
  const barW = Math.max(8, iw - 28) // leaves room for "39%" and "user 31  sys 8" after the bar
  meter(cv, e, y + 1, barW, c.total / 100)
  e = cv.text(e + barW + 1, y + 1, pct(c.total).padStart(4), heat(c.total / 100))
  cv.text(e + 1, y + 1, `user ${Math.round(c.user)}  sys ${Math.round(c.sys)}`, C.text, DEFAULT, ix + iw - 1)
  // below the bar: a history chart on whatever rows are left, then the per-core bars (or the load average)
  const inner = h - 2
  const cell = 18 // "C00 ▕████▏  88%" and a gap
  const perRow = Math.max(1, Math.floor(iw / cell))
  const coreRows = smp.perCore && smp.perCore.length > 0 ? Math.ceil(smp.perCore.length / perRow) : smp.load ? 1 : 0
  const chartH = clamp(inner - 1 - coreRows, 0, 6)
  if (chartH >= 1) {
    label(cv, ix, y + 2, 'TREND')
    areaChart(cv, ix + 6, y + 2, Math.max(4, iw - 6), chartH, s.cpuHist, 100)
  }
  const row = y + 2 + chartH
  if (smp.perCore && smp.perCore.length > 0) {
    smp.perCore.forEach((v, i) => {
      const r = row + Math.floor(i / perRow)
      if (r > y + h - 2) return
      const cx = ix + (i % perRow) * cell
      const l = cv.text(cx, r, `C${String(i).padStart(2, '0')} `, C.dim)
      meter(cv, l, r, 6, v / 100)
      cv.text(l + 7, r, pct(v).padStart(4), heat(v / 100))
    })
  } else if (smp.load && row <= y + h - 2) {
    e = label(cv, ix, row, 'LOAD ')
    e = cv.text(e, row, smp.load.map((n) => n.toFixed(2)).join('  '), C.text)
    if (smp.cores) cv.text(e + 2, row, `${smp.cores} cores`, C.dim)
  }
}

function memPanel(cv: Canvas, s: SysState, x: number, y: number, w: number, h: number): void {
  if (w < 24 || h < 4) return
  const smp = s.sample
  cv.frame(x, y, w, h, { color: C.cyan, label: 'MEMORY', labelColor: C.hot })
  const ix = x + 2
  const iw = w - 4
  if (!smp?.mem) { label(cv, ix, y + 1, smp ? 'memory is not available here' : 'reading …'); return }
  const m = smp.mem
  const frac = m.used / m.total
  const barW = Math.max(8, iw - 14)
  // segments: what is in use (split on macOS), cached files, then free
  const parts = m.app != null && m.wired != null && m.compressed != null
    ? [{ frac: m.app / m.total, color: C.cyan }, { frac: m.wired / m.total, color: C.blue }, { frac: m.compressed / m.total, color: C.magenta }, { frac: m.cached / m.total, color: C.dim }]
    : [{ frac: m.used / m.total, color: heat(frac) }, { frac: m.cached / m.total, color: C.dim }]
  stacked(cv, ix, y + 1, barW, parts)
  cv.text(ix + barW + 1, y + 1, pct(frac * 100).padStart(4), heat(frac))
  let row = y + 2
  if (row <= y + h - 2) {
    let e = label(cv, ix, row, 'USED ')
    e = cv.text(e, row, `${fmtBytes(m.used)} of ${fmtBytes(m.total)}`, C.hot)
    e = label(cv, e + 2, row, 'FREE ')
    cv.text(e, row, fmtBytes(m.free), C.text, DEFAULT, ix + iw - 1)
    row++
  }
  if (row <= y + h - 2 && m.app != null) {
    let e = cv.text(ix, row, '█', C.cyan)
    e = label(cv, e, row, ` APP ${fmtBytes(m.app)}  `, C.text)
    e = cv.text(e, row, '█', C.blue)
    e = label(cv, e, row, ` WIRED ${fmtBytes(m.wired ?? 0)}  `, C.text)
    e = cv.text(e, row, '█', C.magenta)
    cv.text(e, row, ` COMPRESSED ${fmtBytes(m.compressed ?? 0)}`, C.text, DEFAULT, ix + iw - 1)
    row++
  }
  if (row <= y + h - 2) {
    let e = label(cv, ix, row, 'SWAP ')
    e = cv.text(e, row, smp.swap && smp.swap.total > 0 ? `${fmtBytes(smp.swap.used)} of ${fmtBytes(smp.swap.total)}` : 'none', C.text)
    if (smp.pressure) {
      e = label(cv, e + 2, row, 'PRESSURE ')
      cv.text(e, row, smp.pressure, smp.pressure === 'normal' ? C.hot : smp.pressure === 'warn' ? C.yellow : C.alert)
    }
    row++
  }
  const chartH = clamp(y + h - 1 - row, 0, 6)
  if (chartH >= 1) {
    label(cv, ix, row, 'TREND')
    areaChart(cv, ix + 6, row, Math.max(4, iw - 6), chartH, s.memHist, 100)
  }
}

function procPanel(cv: Canvas, s: SysState, x: number, y: number, w: number, h: number): void {
  if (w < 30 || h < 4) return
  cv.frame(x, y, w, h, { color: C.cyan, label: 'PROCESSES', labelColor: C.hot })
  const smp = s.sample
  const ix = x + 2
  const iw = w - 4
  if (!smp || smp.procs.length === 0) { label(cv, ix, y + 1, smp ? 'process list is not available here' : 'reading …'); return }
  const rows = h - 3
  const side = iw >= 62 // two lists side by side, else one list after the other
  const draw = (x0: number, width: number, title: string, list: typeof smp.procs, by: 'cpu' | 'mem', top: number, count: number) => {
    cv.text(x0, top, title, C.dim, DEFAULT, x0 + width - 1)
    const nameW = Math.max(6, width - 19)
    list.slice(0, count).forEach((p, i) => {
      const r = top + 1 + i
      cv.text(x0, r, String(p.pid).padStart(6), C.dim)
      cv.text(x0 + 7, r, `${p.cpu.toFixed(1)}%`.padStart(6), by === 'cpu' ? heat(p.cpu / 100) : C.text)
      cv.text(x0 + 14, r, fmtBytes(p.rssKb * 1024).padStart(5), by === 'mem' ? C.hot : C.text)
      cv.text(x0 + 20, r, clip(p.name, nameW), C.hot, DEFAULT, x0 + width - 1)
    })
  }
  if (side) {
    const half = Math.floor(iw / 2)
    draw(ix, half - 1, '   PID   CPU    MEM NAME  (top by CPU)', topByCpu(smp.procs, rows - 1), 'cpu', y + 1, rows - 1)
    draw(ix + half, iw - half, '   PID   CPU    MEM NAME  (top by memory)', topByMem(smp.procs, rows - 1).filter((p) => p.rssKb > 0), 'mem', y + 1, rows - 1)
  } else {
    const each = Math.max(1, Math.floor((rows - 2) / 2))
    draw(ix, iw, '   PID   CPU    MEM NAME  (top by CPU)', topByCpu(smp.procs, each), 'cpu', y + 1, each)
    draw(ix, iw, '   PID   CPU    MEM NAME  (top by memory)', topByMem(smp.procs, each).filter((p) => p.rssKb > 0), 'mem', y + 2 + each, each)
  }
}

// ---------- the pane ----------
export function renderSystemPane(s: SysState, cols: number, rows: number): Canvas {
  const H = Math.max(12, rows)
  const cv = new Canvas(cols, H)
  const body = H - 1
  const smp = s.sample
  const platformName = smp ? (smp.platform === 'darwin' ? 'macOS' : smp.platform === 'linux' ? 'Linux' : 'this system') : 'system'

  // headline
  cv.frame(0, 0, cols, 4, { color: C.hot, label: 'SYSTEM', labelColor: C.white, tab: `${platformName} · every ${Math.round(s.everyMs / 1000)}s`, tabColor: C.cyan, tabInset: 6 })
  if (!smp) {
    cv.text(2, 1, s.error ? `could not read the system: ${s.error}` : 'reading the system …', s.error ? C.alert : C.dim, DEFAULT, cols - 3)
  } else {
    let x = 2
    const stat = (name: string, value: string, color: number = C.hot) => {
      const e = cv.text(x, 1, name + ' ', C.dim)
      x = cv.text(e, 1, value, color, DEFAULT, cols - 3) + 2
    }
    if (smp.cpu) stat('CPU', pct(smp.cpu.total), heat(smp.cpu.total / 100))
    if (smp.mem) stat('MEM', `${pct((smp.mem.used / smp.mem.total) * 100)} (${fmtBytes(smp.mem.used)} of ${fmtBytes(smp.mem.total)})`, heat(smp.mem.used / smp.mem.total))
    if (smp.swap && smp.swap.total > 0) stat('SWAP', fmtBytes(smp.swap.used), C.text)
    if (smp.load) stat('LOAD', smp.load.map((n) => n.toFixed(2)).join(' '), C.text)
    x = 2
    const cv2 = cv
    const put = (name: string, value: string, color: number = C.hot) => { const e = cv2.text(x, 2, name + ' ', C.dim); x = cv2.text(e, 2, value, color, DEFAULT, cols - 3) + 2 }
    if (smp.thermal) put('THERMAL', smp.thermal.state === 'throttled' ? `slowed to ${smp.thermal.limit}%` : smp.thermal.state, smp.thermal.state === 'throttled' ? C.alert : C.hot)
    if (smp.cores) put('CORES', String(smp.cores), C.text)
    if (smp.pressure) put('PRESSURE', smp.pressure, smp.pressure === 'normal' ? C.hot : smp.pressure === 'warn' ? C.yellow : C.alert)
  }

  // panels
  const top = 4
  const areaH = body - top
  const wide = cols >= 100 && areaH >= 14
  const perCoreRows = smp?.perCore ? Math.ceil(smp.perCore.length / Math.max(1, Math.floor((Math.floor(cols * 0.55) - 4) / 16))) : 0
  if (wide) {
    const leftW = Math.floor(cols * 0.55)
    const cpuH = clamp(4 + Math.max(1, perCoreRows), 6, Math.floor(areaH * 0.5))
    cpuPanel(cv, s, 0, top, leftW, cpuH)
    memPanel(cv, s, 0, top + cpuH, leftW, Math.max(4, areaH - cpuH))
    procPanel(cv, s, leftW, top, cols - leftW, areaH)
  } else {
    // one column: CPU, memory, processes, each as tall as it needs and the rest dropped when short
    let y = top
    let left = areaH
    const place = (h: number, f: (y: number, h: number) => void) => { const hh = Math.min(h, left); if (hh >= 4) { f(y, hh); y += hh; left -= hh } }
    place(smp?.perCore ? 5 : 5, (yy, hh) => cpuPanel(cv, s, 0, yy, cols, hh))
    place(7, (yy, hh) => memPanel(cv, s, 0, yy, cols, hh))
    place(Math.max(6, left), (yy, hh) => procPanel(cv, s, 0, yy, cols, hh))
  }

  // status strip, like the other tabs
  const age = smp ? Math.max(0, Math.round((s.now - smp.at) / 1000)) : 0
  const bar = ` 4 [system]  ${platformName}  ${smp ? `sampled ${age}s ago` : 'sampling'}${s.loading ? ' …' : ''}`
  for (let x = 0; x < cols; x++) cv.set(x, H - 1, 32, C.ink, lerp3(C.cyan, C.blue, C.magenta, x / Math.max(1, cols - 1)))
  cv.text(0, H - 1, bar, C.ink)
  const right = 'read-only: nothing is saved'
  if (cols > bar.length + right.length + 2) cv.text(cols - right.length - 1, H - 1, right, C.ink)
  return cv
}

// A plain-text snapshot for the transcript (/grid system text).
export function systemText(s: SysState): string {
  const smp = s.sample
  if (!smp) return 'No reading yet: open the SYSTEM tab (/grid system) and try again.'
  const lines: string[] = [`SYSTEM · ${smp.platform}`]
  if (smp.cpu) lines.push(`cpu      ${pct(smp.cpu.total)} (user ${Math.round(smp.cpu.user)}, sys ${Math.round(smp.cpu.sys)})${smp.cores ? ` · ${smp.cores} cores` : ''}`)
  if (smp.load) lines.push(`load     ${smp.load.map((n) => n.toFixed(2)).join('  ')}`)
  if (smp.mem) {
    const m = smp.mem
    lines.push(`memory   ${fmtBytes(m.used)} of ${fmtBytes(m.total)} (${pct((m.used / m.total) * 100)}) · cached ${fmtBytes(m.cached)} · free ${fmtBytes(m.free)}`)
    if (m.app != null) lines.push(`         app ${fmtBytes(m.app)} · wired ${fmtBytes(m.wired ?? 0)} · compressed ${fmtBytes(m.compressed ?? 0)}`)
  }
  if (smp.swap) lines.push(`swap     ${smp.swap.total > 0 ? `${fmtBytes(smp.swap.used)} of ${fmtBytes(smp.swap.total)}` : 'none'}${smp.pressure ? ` · pressure ${smp.pressure}` : ''}`)
  if (smp.thermal) lines.push(`thermal  ${smp.thermal.state === 'throttled' ? `slowed to ${smp.thermal.limit}%` : smp.thermal.state}`)
  const cpuTop = topByCpu(smp.procs, 5)
  if (cpuTop.length) lines.push('top cpu  ' + cpuTop.map((p) => `${p.name} ${p.cpu.toFixed(0)}%`).join(' · '))
  const memTop = topByMem(smp.procs, 5)
  if (memTop.length) lines.push('top mem  ' + memTop.map((p) => `${p.name} ${fmtBytes(p.rssKb * 1024)}`).join(' · '))
  for (const n of smp.notes) lines.push('note     ' + n)
  return lines.join('\n')
}
